const HOST='https://www.neuvetra.ai',AUTH='https://icockcoguyadhryzydvl.supabase.co',PROFILE='m77-hosted-continuation-v1'
const JOURNAL=path.resolve(import.meta.dir,'../../.superpowers/m77-hosted-continuation.jsonl'),ORIGINAL=path.resolve(import.meta.dir,'../../.superpowers/m77-hosted-journey.jsonl'),PREVIOUS=path.resolve(import.meta.dir,'../../.superpowers/m76-hosted-continuation.jsonl')
type Mode='diagnostic'|'baseline'|'exercise'|'revisit'
